CREATE TABLE bee_journal_records(owner TEXT NOT NULL, collection TEXT NOT NULL, id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(owner,collection,id));
CREATE TABLE bee_journal_record_state(owner TEXT PRIMARY KEY, revision INTEGER NOT NULL);
CREATE TRIGGER bee_records_after_insert AFTER INSERT ON bee_journals BEGIN
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='hives' AND id NOT IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.payload,'$.hives'));
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'hives',json_extract(value,'$.id'),value FROM json_each(NEW.payload,'$.hives') WHERE 1 ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='tasks' AND id NOT IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.payload,'$.tasks'));
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'tasks',json_extract(value,'$.id'),value FROM json_each(NEW.payload,'$.tasks') WHERE 1 ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='notes' AND id NOT IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.payload,'$.notes'));
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'notes',json_extract(value,'$.id'),value FROM json_each(NEW.payload,'$.notes') WHERE 1 ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='flowerings' AND id NOT IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.payload,'$.flowerings'));
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'flowerings',json_extract(value,'$.id'),value FROM json_each(NEW.payload,'$.flowerings') WHERE 1 ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='breeding' AND id NOT IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.payload,'$.breeding'));
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'breeding',json_extract(value,'$.id'),value FROM json_each(NEW.payload,'$.breeding') WHERE 1 ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='queens' AND id NOT IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.payload,'$.queens'));
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'queens',json_extract(value,'$.id'),value FROM json_each(NEW.payload,'$.queens') WHERE 1 ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='expenses' AND id NOT IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.payload,'$.expenses'));
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'expenses',json_extract(value,'$.id'),value FROM json_each(NEW.payload,'$.expenses') WHERE 1 ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='settings' AND id='region' AND json_type(NEW.payload,'$.region') IS NULL;
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'settings','region',json_quote(json_extract(NEW.payload,'$.region')) WHERE json_type(NEW.payload,'$.region')='text' ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='settings' AND id='language' AND json_type(NEW.payload,'$.language') IS NULL;
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'settings','language',json_quote(json_extract(NEW.payload,'$.language')) WHERE json_type(NEW.payload,'$.language')='text' ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='settings' AND id='hemisphere' AND json_type(NEW.payload,'$.hemisphere') IS NULL;
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'settings','hemisphere',json_quote(json_extract(NEW.payload,'$.hemisphere')) WHERE json_type(NEW.payload,'$.hemisphere')='text' ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
DELETE FROM bee_journal_records WHERE owner=NEW.owner AND collection='settings' AND id='season' AND json_type(NEW.payload,'$.season') IS NULL;
INSERT INTO bee_journal_records(owner,collection,id,payload) SELECT NEW.owner,'settings','season',json_quote(json_extract(NEW.payload,'$.season')) WHERE json_type(NEW.payload,'$.season')='text' ON CONFLICT(owner,collection,id) DO UPDATE SET payload=excluded.payload WHERE payload<>excluded.payload;
INSERT INTO bee_journal_record_state(owner,revision) VALUES(NEW.owner,NEW.revision) ON CONFLICT(owner) DO UPDATE SET revision=excluded.revision;
END;
