CREATE TRIGGER bee_records_after_delete AFTER DELETE ON bee_journals BEGIN DELETE FROM bee_journal_records WHERE owner=OLD.owner; DELETE FROM bee_journal_record_state WHERE owner=OLD.owner; END;
